def generate(level=1, **kwargs):
    from core.prompts.domain_function_library import PolynomialOps

    dividend_coefficients = [-6, -4, 3]
    divisor_coefficients = [1, -2]

    quotient_coefficients, remainder_coefficients = PolynomialOps.div_qr(dividend_coefficients, divisor_coefficients)

    question_text = "Divide the polynomial with coefficients {} by the linear polynomial defined by leading coefficient {} and constant term {}. Report the quotient coefficients (highest degree first) and the single remainder value."

    correct_answer = {
        "quotient_coefficients": quotient_coefficients,
        "remainder_coefficients": [int(remainder_coefficients[0])] if isinstance(remainder_coefficients[0], int) else list(map(str, remainder_coefficients))
    }

    oracle_payload = {"dividend_coefficients": dividend_coefficients, "divisor_coefficients": divisor_coefficients}

    return {
        "question_text": question_text.format(dividend_coefficients, divisor_coefficients[0], divisor_coefficients[-1]),
        "correct_answer": correct_answer,
        "oracle_payload": oracle_payload
    }

